const upsertReadCursor = `-- name: UpsertReadCursor :exec
INSERT INTO read_cursors (user_id, room_id, seq) VALUES (?, ?, ?)
ON CONFLICT (user_id, room_id) DO UPDATE SET seq = MAX(read_cursors.seq, excluded.seq)
`

type UpsertReadCursorParams struct {
	UserID string
	RoomID string
	Seq    int64
}

// A read cursor only moves forward.
func (q *Queries) UpsertReadCursor(ctx context.Context, arg UpsertReadCursorParams) error {
	_, err := q.db.ExecContext(ctx, upsertReadCursor, arg.UserID, arg.RoomID, arg.Seq)
	return err
}
